script:
(function () {
  'use strict';
  // Gross distribution needed to keep a target after-tax amount, with the withdrawal taxed on top of
  // the year's other income at the actual 2026 federal brackets (not a flat withholding rate).
  //   federal tax on W = tax(other + W) - tax(other), where
  //     tax(x) = brackets(max(0, x - standard deduction - 65+ additions - senior deduction))
  //     senior deduction = $6,000 per person 65+, less 6% of income above $75,000 ($150,000 joint)
  //   kept(W) = W - federal tax on W - state% x W - penalty% x W - fee
  //   The gross W with kept(W) = target is found by bisection (kept rises with W because every
  //   marginal rate stays below 100%).
  // Checked in Node (scratch tests, hand calculations): single, $50,000 other income, keep $10,000,
  //   no state -> $11,363.64 (all in the 12% band: 10,000 / 0.88); single, $0 other income, keep
  //   $10,000 -> $10,000 (inside the $16,100 standard deduction); MFJ $60,000 other, keep $20,000,
  //   5% state -> $24,096.39 (12% band: 20,000 / 0.83); single $100,000 other, keep $20,000 ->
  //   crosses 22% -> 24% at $105,700 taxable -> $25,742.11 (21,800 + 2,996 / 0.76); 10% penalty
  //   and $50 fee, $50,000 other -> $12,884.62 (10,050 / 0.78); the forward calculation of every result returns the
  //   target to the cent. Senior deduction phase-out: single 65+, $90,000 income -> $5,100 (taxable $66,750).
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Additional standard deduction (65+) and the senior deduction ($6,000 per person 65+, 2025-2028,
  //   6% phase-out, not for married filing separately): IRC 63(f) and 151(d)(5)(C) as amended by
  //   P.L. 119-21, inflation-adjusted per Rev. Proc. 2025-32. Same constants as
  //   take-home-paycheck-calculator and income-tax-calculator.
  // 10% additional tax on early distributions: IRC 72(t). 20% withholding on eligible rollover
  //   distributions paid to you: IRC 3405(c); 10% default on IRA payouts: IRC 3405(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var ADDITIONAL_65 = { single: 2050, hoh: 2050, mfj: 1650, mfs: 1650 }; // per person 65+
  var SENIOR_DEDUCTION = 6000, SENIOR_PHASEOUT_RATE = 0.06;
  var SENIOR_PHASEOUT_START = { single: 75000, hoh: 75000, mfj: 150000, mfs: 0 };
  var EARLY_PENALTY = 0.10;
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = RATES[0];
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: taxable > 0 ? marginal : 0 };
  }

  // income: gross ordinary income (AGI); seniors: number of filers 65+.
  function federal(income, status, seniors) {
    var deduction = STANDARD_DEDUCTION[status] + seniors * ADDITIONAL_65[status];
    if (status !== 'mfs' && seniors > 0) {
      deduction += seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_PHASEOUT_RATE * Math.max(0, income - SENIOR_PHASEOUT_START[status]));
    }
    var taxable = Math.max(0, income - deduction);
    var bt = bracketTax(taxable, BRACKETS[status]);
    return { tax: bt.tax, marginal: bt.marginal, taxable: taxable };
  }

  // o: other, status, seniors, state, penalty (decimals), fee
  function forward(gross, o) {
    var before = federal(o.other, o.status, o.seniors), after = federal(o.other + gross, o.status, o.seniors);
    var fed = after.tax - before.tax, st = gross * o.state, pen = gross * o.penalty;
    return { gross: gross, fed: fed, state: st, pen: pen, fee: o.fee, net: gross - fed - st - pen - o.fee,
             before: before.marginal, after: after.marginal };
  }

  function grossFor(target, o) {
    if (target <= 0 && o.fee <= 0) return forward(0, o);
    var lo = 0, hi = Math.max(1, target + o.fee);
    for (var k = 0; k < 60 && forward(hi, o).net < target; k++) hi *= 2;
    for (var j = 0; j < 200; j++) {
      var mid = (lo + hi) / 2;
      if (forward(mid, o).net < target) lo = mid; else hi = mid;
      if (hi - lo < 1e-7) break;
    }
    return forward(hi, o);
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function checked(id) { var el = document.getElementById(id); return !!(el && el.checked); }
  function pctOf(x) { return Math.round(x * 100) + '%'; }

  function update() {
    var target = num('gdNet'), other = num('gdOther'), state = num('gdState'), withhold = num('gdWithhold'),
        fee = num('gdFee'), status = document.getElementById('gdStatus').value;
    var penalty = checked('gdPenalty');
    var spouseWrap = document.getElementById('gdSpouseWrap');
    if (spouseWrap) spouseWrap.hidden = status !== 'mfj';
    var error = document.getElementById('gdError');
    var bad = [target, other, state, withhold, fee].some(isNaN) || target < 0 || other < 0 || state < 0 || state > 15 ||
              withhold < 0 || withhold > 100 || fee < 0 || !BRACKETS[status];
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, a state rate from 0% to 15% and withholding from 0% to 100%.';
      return;
    }
    var seniors = (checked('gdYou65') ? 1 : 0) + (status === 'mfj' && checked('gdSpouse65') ? 1 : 0);
    var o = { other: other, status: status, seniors: seniors, state: state / 100, penalty: penalty ? EARLY_PENALTY : 0, fee: fee };
    var r = grossFor(target, o);
    var cost = r.fed + r.state + r.pen;
    set('gdGross', money.format(r.gross));
    set('gdCost', money.format(cost));
    set('gdEff', r.gross > 0 ? pct.format(cost / r.gross) : pct.format(0));
    set('gdRowGross', money.format(r.gross));
    set('gdRowFed', money.format(r.fed));
    set('gdRowState', money.format(r.state));
    set('gdRowPen', money.format(r.pen));
    set('gdRowFee', money.format(r.fee));
    set('gdRowNet', money.format(Math.max(0, r.net)));
    set('gdBrackets', pctOf(r.before) + ' / ' + pctOf(r.after));
    var withheld = r.gross * withhold / 100;
    var cash = r.gross - withheld - r.fee;
    var settle = r.fed + r.pen - withheld;
    set('gdCash', 'With ' + withhold + '% federal withholding the plan pays you ' + money.format(cash) + ' and sends ' +
        money.format(withheld) + ' to the IRS. ' + (settle >= 0.005
          ? 'Expect to owe about ' + money.format(settle) + ' more federal tax' + (r.pen > 0 ? ' and penalty' : '') + ' when you file your ' + TAX_YEAR + ' return'
          : settle <= -0.005 ? 'That is about ' + money.format(-settle) + ' more than the federal tax' + (r.pen > 0 ? ' and penalty' : '') +
            ' on this withdrawal, which comes back as part of your ' + TAX_YEAR + ' refund'
          : 'That matches the federal tax on this withdrawal') +
        (r.state >= 0.005 ? ', and set aside ' + money.format(r.state) + ' for state tax unless the plan withholds it.' : '.'));

    var amounts = [5000, 10000, 25000, 50000, 75000, 100000, 150000];
    if (amounts.indexOf(target) < 0) { amounts.push(target); amounts.sort(function (a, b) { return a - b; }); }
    var body = document.getElementById('gdGrid');
    body.textContent = '';
    amounts.forEach(function (amt) {
      var x = grossFor(amt, o), c = x.fed + x.state + x.pen;
      var tr = document.createElement('tr');
      [whole.format(amt) + (amt === target ? ' (yours)' : ''), whole.format(x.gross), whole.format(c),
       x.gross > 0 ? pct.format(c / x.gross) : pct.format(0), pctOf(x.after)].forEach(function (v, idx) {
        var td = document.createElement(idx === 0 ? 'th' : 'td');
        if (idx === 0) td.setAttribute('scope', 'row');
        td.textContent = v;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('gdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
